<section class="container py-4"><div class="mb-4"><h1 class="h2 fw-bold">Lịch sử khám của tôi</h1><p class="text-secondary">Chỉ hiển thị thông tin khám thuộc hồ sơ của tài khoản hiện tại.</p></div><div class="accordion" id="historyAccordion"><?php foreach ($visits as $i=>$v): ?><div class="accordion-item"><h2 class="accordion-header"><button class="accordion-button <?= $i?'collapsed':'' ?>" type="button" data-bs-toggle="collapse" data-bs-target="#visit<?= (int)$v['MaLKham'] ?>">Lần khám #<?= (int)$v['MaLKham'] ?> · <?= e($v['NgayGioKham']) ?> · <?= e($v['TenBacSi']) ?></button></h2><div id="visit<?= (int)$v['MaLKham'] ?>" class="accordion-collapse collapse <?= $i?'':'show' ?>" data-bs-parent="#historyAccordion"><div class="accordion-body"><p><strong>Lý do:</strong> <?= e($v['LyDoKham']) ?></p><p><strong>Triệu chứng:</strong> <?= e($v['TrieuChung']) ?></p><p><strong>Chẩn đoán:</strong> <?= e($v['ChanDoan']) ?></p><p><strong>Kết quả:</strong> <?= e($v['KetQuaKham']) ?></p><p><strong>Hướng xử lý:</strong> <?= e($v['HuongXuLy']) ?></p><?php if (!empty($v['MaDonThuoc'])): ?><hr><p><strong>Đơn thuốc #<?= (int)$v['MaDonThuoc'] ?>:</strong> <?= e($v['DanhSachThuoc']) ?></p><p><strong>Lời dặn:</strong> <?= e($v['LoiDanThuoc']) ?></p><?php endif; ?></div></div></div><?php endforeach; ?><?php if (!$visits): ?><div class="empty-state">Chưa có lịch sử khám được ghi nhận.</div><?php endif; ?></div></section>
